      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "ON123300, a piperazine-containing kinase inhibitor with an aminopyrimidine core, exhibited favorable in vivo brain/plasma partitioning, supporting CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Imatinib, a piperazine/aminopyrimidine kinase inhibitor, has CSF concentrations <1% of plasma in mice, indicating that some related inhibitors are efflux-limited; however, this is outweighed by direct brain-penetrant evidence from closer CDK4/6 analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
